const fs = require("node:fs");
const path = require("node:path");
const {
  canonicalizeEntryKey,
  reconcileFrenchPronominalConceptKey,
} = require("../../admin/js/entry-key-canonicalization-0.1.js");

const ALLOWED_COUNTS = new Set([10, 20, 30, 50]);
const ALLOWED_LEVELS = new Set(["A1", "A2", "B1", "B2"]);
const ALLOWED_PARTS_OF_SPEECH = new Set(["noun", "verb", "adjective", "adverb"]);
const DEFAULT_MODEL = "gpt-4.1-mini";
const DICTIONARY_LEMMA_INSTRUCTIONS = [
  "Les formes proposées doivent être des lemmes dictionnaires, pas des formes fléchies.",
  "Pour chaque langue : noms au singulier ; verbes à l’infinitif ; adjectifs sous leur forme canonique de dictionnaire ; adverbes sous leur forme non fléchie ; déterminants et pronoms sous leur forme canonique la plus neutre.",
  "Ne propose pas de pluriels contextuels, de formes conjuguées ni de formes accordées en genre ou en nombre, sauf si la forme est lexicalisée ou réellement invariable.",
  "Exemples adjectivaux : FR utiles → utile ; ES útiles → útil ; IT utili → utile ; PT úteis → útil.",
  "Exemples nominaux : FR élèves → élève ; ES alumnos → alumno ; IT studenti → studente ; PT alunos → aluno.",
  "Exemples verbaux : FR mangent → manger ; ES comen → comer ; IT mangiano → mangiare ; PT comem → comer.",
];
const FRENCH_CONCEPT_KEY_INSTRUCTIONS = [
  "Pour chaque nouveau concept, nomme entry_key en français à partir du sens visé. Utilise un nom conceptuel français naturel : infinitif pour un verbe, singulier pour un nom, forme dictionnaire pour un adjectif ou un adverbe.",
  "La clé technique finale doit être canonicalisée en ASCII, en majuscules et avec des underscores. N’utilise pas l’anglais comme langue implicite de la clé : l’anglais reste une forme linguistique de comparaison. Ne déduis pas la clé d’une forme espagnole, italienne, portugaise ou d’une forme fléchie.",
  "Si le terme est polysémique ou si un concept proche existe, ajoute si nécessaire un qualificatif sémantique français bref. N’ajoute pas systématiquement une catégorie grammaticale au nom. Toute clé incertaine doit rester un brouillon à vérifier humainement.",
  "Exemples : souffrir → SOUFFRIR ; préoccupant → PREOCCUPANT ; augmenter → AUGMENTER ; banque au sens financier → BANQUE_FINANCE ; banque comme collection de données → BANQUE_DONNEES ; voler dans les airs → VOLER_DEPLACEMENT_AERIEN ; voler quelque chose → VOLER_DEROBER.",
  "Contre-exemples : ne produis pas SUFFER pour souffrir, WORRISOME pour préoccupant, SOFFRIR à partir de l’italien ou du portugais, ni systématiquement PREOCCUPANT_ADJECTIVE.",
  "Pour un verbe pronominal français, conserve le pronom dans le nom conceptuel et sépare-le par un underscore : s’élever → S_ELEVER ; s'enfuir → S_ENFUIR ; se souvenir → SE_SOUVENIR ; se lever → SE_LEVER. Ne supprime pas simplement l’apostrophe ou l’espace. Ne produis pas SELEVER pour s’élever, SENFUIR pour s’enfuir, ni SESOUVENIR pour se souvenir. N’insère aucun underscore pronominal dans un verbe non pronominal : semer → SEMER ; servir → SERVIR ; serrer → SERRER.",
];

class AdminAiError extends Error {
  constructor(status, code, message, field) {
    super(message);
    this.name = "AdminAiError";
    this.status = status;
    this.code = code;
    this.field = field;
  }
}

function loadAdminOpenAiConfig() {
  const values = {};
  const envPath = path.resolve(__dirname, "../../admin/.env");
  if (fs.existsSync(envPath)) {
    for (const rawLine of fs.readFileSync(envPath, "utf8").split(/\r?\n/)) {
      const line = rawLine.trim();
      if (!line || line.startsWith("#")) continue;
      const separator = line.indexOf("=");
      if (separator < 1) continue;
      const key = line.slice(0, separator).trim();
      let value = line.slice(separator + 1).trim();
      if ((value.startsWith('"') && value.endsWith('"'))
          || (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      values[key] = value;
    }
  }

  return {
    apiKey: process.env.OPENAI_API_KEY || values.OPENAI_API_KEY || "",
    model: process.env.OPENAI_MODEL || values.OPENAI_MODEL || DEFAULT_MODEL,
  };
}

function validateDomainCandidateRequest(body, activeLanguages) {
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    throw new AdminAiError(400, "INVALID_REQUEST", "Le corps doit être un objet JSON.");
  }

  const domain = typeof body.domain === "string" ? body.domain.trim() : "";
  if (domain.length < 2 || domain.length > 100) {
    throw new AdminAiError(
      400,
      "INVALID_DOMAIN",
      "Le domaine doit contenir entre 2 et 100 caractères.",
      "domain"
    );
  }

  const count = Number(body.count);
  if (count > 50) {
    throw new AdminAiError(400, "CANDIDATE_LIMIT_EXCEEDED", "Le nombre de propositions est limité à 50.", "count");
  }
  if (!ALLOWED_COUNTS.has(count)) {
    throw new AdminAiError(400, "INVALID_CANDIDATE_COUNT", "Le nombre doit être 10, 20, 30 ou 50.", "count");
  }

  if (!Array.isArray(body.languages) || body.languages.length === 0) {
    throw new AdminAiError(400, "INVALID_LANGUAGES", "Sélectionnez au moins une langue active.", "languages");
  }
  const activeCodes = new Set(activeLanguages.map((language) => language.code));
  const languages = [...new Set(body.languages)];
  if (languages.length !== body.languages.length
      || languages.some((code) => typeof code !== "string" || !activeCodes.has(code))) {
    throw new AdminAiError(400, "INVALID_LANGUAGES", "Les langues doivent être actives et sans doublon.", "languages");
  }

  const level = typeof body.level === "string" ? body.level.toUpperCase() : "";
  if (!ALLOWED_LEVELS.has(level)) {
    throw new AdminAiError(400, "INVALID_LEVEL", "Le niveau doit être A1, A2, B1 ou B2.", "level");
  }

  if (!Array.isArray(body.parts_of_speech) || body.parts_of_speech.length === 0) {
    throw new AdminAiError(400, "INVALID_PARTS_OF_SPEECH", "Sélectionnez au moins une catégorie grammaticale.", "parts_of_speech");
  }
  const partsOfSpeech = [...new Set(body.parts_of_speech)];
  if (partsOfSpeech.length !== body.parts_of_speech.length
      || partsOfSpeech.some((part) => !ALLOWED_PARTS_OF_SPEECH.has(part))) {
    throw new AdminAiError(400, "INVALID_PARTS_OF_SPEECH", "Une catégorie grammaticale est invalide ou répétée.", "parts_of_speech");
  }

  return { domain, count, languages, level, parts_of_speech: partsOfSpeech };
}

function candidateSchema() {
  return {
    type: "object",
    additionalProperties: false,
    required: ["candidates"],
    properties: {
      candidates: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["entry_key", "gloss_fr", "gloss_en", "semantic_domain", "forms"],
          properties: {
            entry_key: { type: "string" },
            gloss_fr: { type: "string" },
            gloss_en: { type: "string" },
            semantic_domain: { type: "string" },
            forms: {
              type: "array",
              items: {
                type: "object",
                additionalProperties: false,
                required: ["language_code", "lemma", "part_of_speech"],
                properties: {
                  language_code: { type: "string" },
                  lemma: { type: "string" },
                  part_of_speech: { type: "string", enum: [...ALLOWED_PARTS_OF_SPEECH] },
                },
              },
            },
          },
        },
      },
    },
  };
}

function extractResponseText(response) {
  if (typeof response.output_text === "string") return response.output_text;
  for (const item of response.output || []) {
    for (const content of item.content || []) {
      if (content.type === "output_text" && typeof content.text === "string") return content.text;
    }
  }
  throw new AdminAiError(502, "OPENAI_EMPTY_RESPONSE", "OpenAI n’a renvoyé aucun contenu exploitable.");
}

function canonicalizeCandidateEntryKey(value, index) {
  try {
    return canonicalizeEntryKey(value);
  } catch {
    throw new AdminAiError(
      502,
      "OPENAI_INVALID_CANDIDATE",
      `La clé technique du candidat ${index + 1} est vide après canonicalisation.`
    );
  }
}

function parseAndValidateCandidateJson(raw, request) {
  let parsed;
  try {
    parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  } catch {
    throw new AdminAiError(502, "OPENAI_INVALID_JSON", "La réponse OpenAI n’est pas un JSON valide.");
  }
  if (!parsed || !Array.isArray(parsed.candidates)) {
    throw new AdminAiError(502, "OPENAI_INVALID_PAYLOAD", "La réponse OpenAI ne contient pas de tableau candidates.");
  }

  const requestedLanguages = new Set(request.languages);
  const requestedPartsOfSpeech = new Set(request.parts_of_speech);
  const candidates = parsed.candidates.slice(0, request.count).map((candidate, index) => {
    if (!candidate || typeof candidate !== "object" || Array.isArray(candidate)) {
      throw new AdminAiError(502, "OPENAI_INVALID_CANDIDATE", `Le candidat ${index + 1} est invalide.`);
    }
    for (const field of ["entry_key", "gloss_fr", "gloss_en", "semantic_domain"] ) {
      if (typeof candidate[field] !== "string") {
        throw new AdminAiError(502, "OPENAI_INVALID_CANDIDATE", `Le champ ${field} du candidat ${index + 1} est invalide.`);
      }
    }
    if (!Array.isArray(candidate.forms)) {
      throw new AdminAiError(502, "OPENAI_INVALID_CANDIDATE", `Les formes du candidat ${index + 1} sont invalides.`);
    }
    const forms = candidate.forms.map((form, formIndex) => {
      if (!form || typeof form.language_code !== "string" || typeof form.lemma !== "string"
          || !ALLOWED_PARTS_OF_SPEECH.has(form.part_of_speech)) {
        throw new AdminAiError(502, "OPENAI_INVALID_FORM", `La forme ${formIndex + 1} du candidat ${index + 1} est invalide.`);
      }
      if (!requestedLanguages.has(form.language_code)) {
        throw new AdminAiError(502, "OPENAI_INVALID_LANGUAGE", `OpenAI a renvoyé une langue non demandée : ${form.language_code}.`);
      }
      if (!requestedPartsOfSpeech.has(form.part_of_speech)) {
        throw new AdminAiError(502, "OPENAI_INVALID_PART_OF_SPEECH", `OpenAI a renvoyé une catégorie non demandée : ${form.part_of_speech}.`);
      }
      return {
        language_code: form.language_code,
        lemma: form.lemma.trim(),
        part_of_speech: form.part_of_speech,
      };
    });
    const proposedEntryKey = canonicalizeCandidateEntryKey(candidate.entry_key, index);
    const reconciledEntryKey = reconcileFrenchPronominalConceptKey(proposedEntryKey, forms);
    return {
      entry_key: reconciledEntryKey.entryKey,
      gloss_fr: candidate.gloss_fr.trim(),
      gloss_en: candidate.gloss_en.trim(),
      semantic_domain: candidate.semantic_domain.trim(),
      forms,
    };
  });

  return { candidates };
}

function buildPrompts(request) {
  const system = [
    "Tu proposes des brouillons lexicaux pour une base d’intercompréhension romane.",
    "Retourne uniquement les données demandées par le schéma JSON.",
    ...FRENCH_CONCEPT_KEY_INSTRUCTIONS,
    "Les formes doivent être usuelles, pédagogiquement pertinentes et distinctes.",
    ...DICTIONARY_LEMMA_INSTRUCTIONS,
    "N’invente pas de langues et n’ajoute aucune explication hors JSON.",
  ].join(" ");
  const user = [
    `Domaine pédagogique : ${request.domain}.`,
    `Niveau approximatif : ${request.level}.`,
    `Nombre exact de propositions : ${request.count}.`,
    `Langues demandées : ${request.languages.join(", ")}.`,
    `Catégories autorisées : ${request.parts_of_speech.join(", ")}.`,
    "Pour chaque concept, fournis si possible une forme dans chaque langue demandée.",
    "semantic_domain doit reprendre un libellé cohérent avec le domaine fourni.",
  ].join(" ");
  return { system, user };
}

async function generateStructuredCandidates(request, prompts, schemaName, options = {}) {
  const config = loadAdminOpenAiConfig();
  const apiKey = options.apiKey ?? config.apiKey;
  const model = options.model ?? config.model;
  const fetchImpl = options.fetchImpl || fetch;
  const schema = options.schema || candidateSchema();
  const parseResponse = options.parseResponse || parseAndValidateCandidateJson;
  const cancellationSignal = options.signal;
  if (!apiKey) {
    throw new AdminAiError(503, "OPENAI_NOT_CONFIGURED", "La clé OpenAI n’est pas configurée côté serveur.");
  }

  const controller = new AbortController();
  let cancelledByClient = Boolean(cancellationSignal?.aborted);
  const cancelFromClient = () => {
    cancelledByClient = true;
    controller.abort();
  };
  if (cancellationSignal && !cancellationSignal.aborted) {
    cancellationSignal.addEventListener("abort", cancelFromClient, { once: true });
  } else if (cancelledByClient) {
    controller.abort();
  }
  const timeout = setTimeout(() => controller.abort(), 90_000);
  try {
    const response = await fetchImpl("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        input: [
          { role: "system", content: [{ type: "input_text", text: prompts.system }] },
          { role: "user", content: [{ type: "input_text", text: prompts.user }] },
        ],
        text: {
          format: {
            type: "json_schema",
            name: schemaName,
            strict: true,
            schema,
          },
        },
      }),
      signal: controller.signal,
    });
    const data = await response.json().catch(() => null);
    if (cancelledByClient || cancellationSignal?.aborted) {
      throw new AdminAiError(499, "OPENAI_CANCELLED", "La génération OpenAI a été annulée par le client.");
    }
    if (!response.ok) {
      const message = data?.error?.message || `OpenAI a répondu avec le statut ${response.status}.`;
      throw new AdminAiError(502, "OPENAI_REQUEST_FAILED", message);
    }
    return {
      ...parseResponse(extractResponseText(data), request),
      model,
      response_id: data.id || null,
    };
  } catch (error) {
    if (error.name === "AbortError") {
      if (cancelledByClient || cancellationSignal?.aborted) {
        throw new AdminAiError(499, "OPENAI_CANCELLED", "La génération OpenAI a été annulée par le client.");
      }
      throw new AdminAiError(504, "OPENAI_TIMEOUT", "La génération OpenAI a dépassé le délai autorisé.");
    }
    if (error instanceof AdminAiError) throw error;
    throw new AdminAiError(502, "OPENAI_UNAVAILABLE", "Impossible de joindre OpenAI.");
  } finally {
    clearTimeout(timeout);
    cancellationSignal?.removeEventListener("abort", cancelFromClient);
  }
}

async function generateDomainCandidates(request, options = {}) {
  return generateStructuredCandidates(
    request,
    buildPrompts(request),
    "dico_ic_domain_candidates",
    options
  );
}

module.exports = {
  AdminAiError,
  DICTIONARY_LEMMA_INSTRUCTIONS,
  FRENCH_CONCEPT_KEY_INSTRUCTIONS,
  buildPrompts,
  candidateSchema,
  generateDomainCandidates,
  generateStructuredCandidates,
  parseAndValidateCandidateJson,
  validateDomainCandidateRequest,
};

const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const {
  FRENCH_CONCEPT_KEY_INSTRUCTIONS,
  buildPrompts,
  parseAndValidateCandidateJson,
} = require("../src/admin-ai-domain");
const { buildTextPrompts } = require("../src/admin-ai-text");

function domainPrompts() {
  return buildPrompts({
    domain: "environnement",
    count: 10,
    languages: ["fr", "es", "it", "pt", "en"],
    level: "A2",
    parts_of_speech: ["noun", "verb", "adjective", "adverb"],
  });
}

function textPrompts() {
  return buildTextPrompts({
    unknown_words: ["souffrir", "préoccupant", "augmenter"],
    languages: ["fr", "es", "it", "pt", "en"],
  });
}

test("les assistants Domaine et Texte réutilisent exactement l’instruction française partagée", () => {
  const domain = domainPrompts().system;
  const text = textPrompts().system;

  assert.ok(FRENCH_CONCEPT_KEY_INSTRUCTIONS.length >= 4);
  for (const instruction of FRENCH_CONCEPT_KEY_INSTRUCTIONS) {
    assert.ok(domain.includes(instruction), instruction);
    assert.ok(text.includes(instruction), instruction);
  }
});

test("l’instruction couvre la politique linguistique, la polysémie et la validation humaine", () => {
  const prompt = domainPrompts().system;

  assert.match(prompt, /nomme entry_key en français à partir du sens visé/);
  assert.match(prompt, /infinitif pour un verbe/);
  assert.match(prompt, /singulier pour un nom/);
  assert.match(prompt, /forme dictionnaire pour un adjectif ou un adverbe/);
  assert.match(prompt, /anglais reste une forme linguistique de comparaison/);
  assert.match(prompt, /forme espagnole, italienne, portugaise ou d’une forme fléchie/);
  assert.match(prompt, /qualificatif sémantique français bref/);
  assert.match(prompt, /N’ajoute pas systématiquement une catégorie grammaticale/);
  assert.match(prompt, /brouillon à vérifier humainement/);
});

test("l’instruction contient les exemples et contre-exemples essentiels sans ambiguïté", () => {
  const prompt = textPrompts().system;

  for (const expected of [
    "souffrir → SOUFFRIR",
    "préoccupant → PREOCCUPANT",
    "augmenter → AUGMENTER",
    "banque au sens financier → BANQUE_FINANCE",
    "banque comme collection de données → BANQUE_DONNEES",
    "voler dans les airs → VOLER_DEPLACEMENT_AERIEN",
    "voler quelque chose → VOLER_DEROBER",
    "SUFFER pour souffrir",
    "WORRISOME pour préoccupant",
    "SOFFRIR à partir de l’italien ou du portugais",
    "PREOCCUPANT_ADJECTIVE",
  ]) {
    assert.ok(prompt.includes(expected), expected);
  }
});

test("la fixture des sept concepts canonicalise seulement les clés et préserve les textes multilingues", () => {
  const concepts = [
    ["souffrir", "SOUFFRIR", "éprouver une souffrance", "suffer", "verb"],
    ["PRÉOCCUPANT", "PREOCCUPANT", "qui suscite de l’inquiétude", "worrisome", "adjective"],
    ["augmenter", "AUGMENTER", "rendre plus grand", "increase", "verb"],
    ["BANQUE_FINANCE", "BANQUE_FINANCE", "établissement financier", "bank", "noun"],
    ["BANQUE_DONNÉES", "BANQUE_DONNEES", "collection organisée de données", "data bank", "noun"],
    ["VOLER_DÉPLACEMENT_AÉRIEN", "VOLER_DEPLACEMENT_AERIEN", "se déplacer dans les airs", "fly", "verb"],
    ["VOLER_DÉROBER", "VOLER_DEROBER", "prendre le bien d’autrui", "steal", "verb"],
  ];
  const parsed = parseAndValidateCandidateJson({
    candidates: concepts.map(([entryKey, _expectedKey, glossFr, lemmaEn, partOfSpeech]) => ({
      entry_key: entryKey,
      gloss_fr: glossFr,
      gloss_en: lemmaEn,
      semantic_domain: "révision humaine",
      forms: [
        { language_code: "fr", lemma: entryKey === "PRÉOCCUPANT" ? "préoccupant" : glossFr, part_of_speech: partOfSpeech },
        { language_code: "en", lemma: lemmaEn, part_of_speech: partOfSpeech },
      ],
    })),
  }, {
    count: 7,
    languages: ["fr", "en"],
    parts_of_speech: ["noun", "verb", "adjective"],
  });

  assert.deepEqual(parsed.candidates.map(candidate => candidate.entry_key), concepts.map(item => item[1]));
  assert.equal(parsed.candidates[1].forms[0].lemma, "préoccupant");
  assert.equal(parsed.candidates[1].gloss_fr, "qui suscite de l’inquiétude");
  assert.equal(parsed.candidates[4].gloss_fr, "collection organisée de données");
  assert.equal(parsed.candidates[5].forms[1].lemma, "fly");
});

test("les deux interfaces présentent calmement la convention et gardent une décision humaine explicite", () => {
  const adminRoot = path.resolve(__dirname, "../../admin");
  for (const file of ["index-admin-ai-domain-0.1.html", "index-admin-ai-text-0.1.html"]) {
    const html = fs.readFileSync(path.join(adminRoot, file), "utf8");
    assert.match(html, /Convention :<\/strong> les nouveaux concepts sont nommés en français\./);
    assert.match(html, /Les clés historiques peuvent conserver une autre langue\./);
    assert.match(html, /<details>/);
    assert.match(html, /validation humaine/);
    assert.match(html, /Créer les entrées sélectionnées/);
  }
});

test("les deux interfaces canonicalisent au blur, recalculent les doublons et n’écrivent qu’au clic", () => {
  const scriptRoot = path.resolve(__dirname, "../../admin/js");
  for (const file of ["admin-ai-domain-0.1.js", "admin-ai-text-0.1.js"]) {
    const script = fs.readFileSync(path.join(scriptRoot, file), "utf8");
    assert.match(script, /addEventListener\("focusout"/);
    assert.match(script, /canonicalizeCandidateForReview/);
    assert.match(script, /refreshCanonicalEntryKeyExistence/);
    assert.match(script, /findDuplicateCanonicalEntryKeys/);
    assert.match(script, /createSelectedButton\.addEventListener\("click", createSelectedCandidates\)/);
    assert.match(script, /async function createSelectedCandidates\(\) \{\s+canonicalizeAllCandidateKeys\(\)/);
  }
});

test("les lots, la progression et l’annulation de l’assistant Texte restent câblés", () => {
  const adminRoot = path.resolve(__dirname, "../../admin");
  const html = fs.readFileSync(path.join(adminRoot, "index-admin-ai-text-0.1.html"), "utf8");
  const script = fs.readFileSync(path.join(adminRoot, "js/admin-ai-text-0.1.js"), "utf8");

  assert.match(html, /id="inflectedBatchSize"/);
  assert.match(html, /id="generationProgress"/);
  assert.match(html, /id="cancelGenerationButton"/);
  assert.match(script, /CancellableGenerationSession/);
  assert.match(script, /cancelLexicalGeneration/);
});
